#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n, mod;
    vector<long long> mem;
    long long total = 1;

    // Read input
    vector<long long> data;
    {
        string line;
        getline(cin, line);
        stringstream ss(line);
        long long val;
        while (ss >> val) {
            data.push_back(val);
        }
    }
    n = data[0];
    mod = data[1];

    mem.assign(n + 1, 0);
    mem[0] = 0;
    mem[1] = 1;

    auto ceil_div = [](long long a, long long b) {
        return (a + b - 1) / b;
    };

    auto mod_add = [&](long long a, long long b) {
        return (a + b) % mod;
    };

    auto mod_mul = [&](long long a, long long b) {
        return (a * b) % mod;
    };

    for (int i = 2; i <= n; ++i) {
        int limit = (int)std::sqrt(i) + 1;
        long long current_sum = total;

        for (int f = 2; f < limit; ++f) {
            current_sum = mod_add(current_sum, mem[i / f]);
        }

        int max_j = i / limit;
        for (int j = 1; j <= max_j; ++j) {
            long long nxt = i / (j + 1);
            current_sum = mod_add(current_sum, mod_mul(i - nxt, mem[j]));
        }

        total = mod_add(total, current_sum);
        mem[i] = current_sum;
    }

    cout << mem[n] << "\n";

    return 0;
}
